1	// @ts-check
2	/**
3	 * PR Release Preview — analyzes individual PR commits (before squash),
4	 * maps changed files to packages, determines bump level per package,
5	 * detects dependency cascades, and auto-applies release labels.
6	 *
7	 * Environment variables (set by workflow):
8	 *   GITHUB_TOKEN  — GitHub API token
9	 *   PR_NUMBER     — Pull request number
10	 *   GITHUB_REPOSITORY — owner/repo
11	 *
12	 * Uses only @actions/core and @actions/github (pre-installed on runners).
13	 */
14	
15	import * as core from '@actions/core';
16	import * as github from '@actions/github';
17	import { readFileSync } from 'node:fs';
18	import { join } from 'node:path';
19	import { BUMP_LEVELS, PATH_TO_LABEL, MONOTONIC_PATHS } from './release-constants.js';
20	
21	// ---------------------------------------------------------------------------
22	// Constants
23	// ---------------------------------------------------------------------------
24	
25	/** Conventional commit regex — matches first line of commit message */
26	const CONVENTIONAL_RE =
27	  /^(?<type>feat|fix|perf|refactor|build|test|docs|style|chore|ci|revert)(?:\((?<scope>[^)]*)\))?(?<breaking>!)?:\s*(?<description>.+)/;
28	
29	/** Commit types that do NOT trigger a version bump (D-39) */
30	const EXEMPT_TYPES = new Set(['docs', 'test', 'chore', 'ci', 'style', 'build', 'revert']);
31	
32	/**
33	 * Map commit type to bump level and label suffix.
34	 * Types not listed here are exempt (no bump).
35	 */
36	const TYPE_TO_BUMP = {
37	  feat: { bump: 'minor', label: 'feat' },
38	  fix: { bump: 'patch', label: 'fix' },
39	  perf: { bump: 'patch', label: 'perf' },
40	  refactor: { bump: 'patch', label: 'refactor' },
41	};
42	
43	/**
44	 * JS dependency graph — production dependencies only (D-24).
45	 * Keys are package paths, values are arrays of dependency paths.
46	 */
47	const JS_DEPS = {
48	  'packages/core': ['packages/crypto'],
49	  'packages/sdk-core': ['packages/api-client', 'packages/core', 'packages/crypto'],
50	  'packages/sdk': ['packages/api-client', 'packages/core', 'packages/crypto', 'packages/sdk-core'],
51	  'apps/web': [
52	    'packages/api-client',
53	    'packages/core',
54	    'packages/crypto',
55	    'packages/sdk',
56	    'packages/sdk-core',
57	  ],
58	  'apps/desktop': ['packages/crypto'],
59	  'apps/tee-worker': ['packages/core', 'packages/crypto', 'packages/sdk-core'],
60	};
61	
62	/**
63	 * Rust dependency graph.
64	 */
65	const RUST_DEPS = {
66	  'crates/core': ['crates/crypto'],
67	  'crates/fuse': ['crates/api-client', 'crates/core', 'crates/crypto'],
68	  'crates/sdk': ['crates/api-client', 'crates/core', 'crates/crypto'],
69	};
70	
71	/** API lock group members (D-05) */
72	const API_LOCK_GROUP = ['apps/api', 'packages/api-client', 'crates/api-client'];
73	
74	/** Monotonic versioning apps — patch bumps become minor (D-08, D-13) */
75	const MONOTONIC_APPS = MONOTONIC_PATHS;
76	
77	/** Comment marker for finding/updating the preview comment */
78	const COMMENT_MARKER = '<!-- release-preview -->';
79	
80	// ---------------------------------------------------------------------------
81	// Helpers
82	// ---------------------------------------------------------------------------
83	
84	/**
85	 * Read release-please-config.json and extract package paths (D-37).
86	 * Excludes root "." package from enforcement.
87	 * @returns {string[]}
88	 */
89	function getPackagePaths() {
90	  const configPath = join(process.cwd(), 'release-please-config.json');
91	  const config = JSON.parse(readFileSync(configPath, 'utf8'));
92	  return Object.keys(config.packages).filter((p) => p !== '.');
93	}
94	
95	/**
96	 * Map a file path to its package path using longest-prefix matching.
97	 * @param {string} filePath
98	 * @param {string[]} packagePaths — sorted by length descending
99	 * @returns {string|null}
100	 */
101	function fileToPackage(filePath, packagePaths) {
102	  for (const prefix of packagePaths) {
103	    if (filePath === prefix || filePath.startsWith(prefix + '/')) {
104	      return prefix;
105	    }
106	  }
107	  return null;
108	}
109	
110	/**
111	 * Build reverse dependency map: for each package, which packages depend on it?
112	 * @param {Record<string, string[]>} deps
113	 * @returns {Record<string, string[]>}
114	 */
115	function buildReverseDeps(deps) {
116	  /** @type {Record<string, string[]>} */
117	  const reverse = {};
118	  for (const [pkg, depList] of Object.entries(deps)) {
119	    for (const dep of depList) {
120	      if (!reverse[dep]) reverse[dep] = [];
121	      reverse[dep].push(pkg);
122	    }
123	  }
124	  return reverse;
125	}
126	
127	/**
128	 * Fetch all pages of a paginated GitHub API endpoint.
129	 * @param {ReturnType<typeof github.getOctokit>} octokit
130	 * @param {string} route
131	 * @param {Record<string, unknown>} params
132	 * @returns {Promise<any[]>}
133	 */
134	async function fetchAllPages(octokit, route, params) {
135	  const items = [];
136	  let page = 1;
137	  const perPage = 100;
138	
139	  while (true) {
140	    let response;
141	    try {
142	      response = await octokit.request(route, {
143	        ...params,
144	        per_page: perPage,
145	        page,
146	      });
147	    } catch (err) {
148	      // Rate limiting: retry with exponential backoff
149	      if (err.status === 403 || err.status === 429) {
150	        for (const delay of [1000, 2000, 4000]) {
151	          core.warning(`Rate limited, retrying in ${delay}ms...`);
152	          await new Promise((r) => setTimeout(r, delay));
153	          try {
154	            response = await octokit.request(route, {
155	              ...params,
156	              per_page: perPage,
157	              page,
158	            });
159	            break;
160	          } catch (retryErr) {
161	            if (retryErr.status !== 403 && retryErr.status !== 429) throw retryErr;
162	          }
163	        }
164	        if (!response) throw err;
165	      } else {
166	        throw err;
167	      }
168	    }
169	
170	    items.push(...response.data);
171	    if (response.data.length < perPage) break;
172	    page++;
173	  }
174	
175	  return items;
176	}
177	
178	// ---------------------------------------------------------------------------
179	// Main
180	// ---------------------------------------------------------------------------
181	
182	async function run() {
183	  const token = process.env.GITHUB_TOKEN;
184	  const prNumber = parseInt(process.env.PR_NUMBER, 10);
185	  const [owner, repo] = process.env.GITHUB_REPOSITORY.split('/');
186	
187	  if (!token || !prNumber || !owner || !repo) {
188	    core.setFailed('Missing required environment variables');
189	    return;
190	  }
191	
192	  const octokit = github.getOctokit(token);
193	
194	  // ------ Check for release:none escape hatch ------
195	  const { data: prData } = await octokit.rest.pulls.get({
196	    owner,
197	    repo,
198	    pull_number: prNumber,
199	  });
200	  const existingLabels = prData.labels.map((l) => l.name);
201	
202	  if (existingLabels.includes('release:none')) {
203	    core.info('release:none label present — skipping enforcement and label computation');
204	    // Post a minimal comment
205	    await postOrUpdateComment(
206	      octokit,
207	      owner,
208	      repo,
209	      prNumber,
210	      [
211	        COMMENT_MARKER,
212	        '## Release Preview',
213	        '',
214	        '`release:none` label present — no version bumps for this PR.',
215	      ].join('\n')
216	    );
217	    return;
218	  }
219	
220	  // ------ Section 1: File-to-Package Mapping ------
221	  const packagePaths = getPackagePaths();
222	  // Sort by length descending for longest-prefix match
223	  packagePaths.sort((a, b) => b.length - a.length);
224	
225	  core.info(`Loaded ${packagePaths.length} package paths from release-please-config.json`);
226	
227	  // ------ Section 2: Commit Parsing ------
228	  const commits = await fetchAllPages(
229	    octokit,
230	    'GET /repos/{owner}/{repo}/pulls/{pull_number}/commits',
231	    { owner, repo, pull_number: prNumber }
232	  );
233	
234	  core.info(`Found ${commits.length} commits in PR #${prNumber}`);
235	
236	  /**
237	   * Per-package bump tracking.
238	   * @type {Map<string, {bump: string, label: string, source: string}>}
239	   */
240	  const packageBumps = new Map();
241	
242	  /** Track warnings for non-conventional commits */
243	  const warnings = [];
244	
245	  /** Track commits analyzed per package for exemption logic */
246	  /** @type {Map<string, Set<string>>} */
247	  const packageCommitTypes = new Map();
248	
249	  for (const commit of commits) {
250	    const message = commit.commit.message;
251	    const firstLine = message.split('\n')[0];
252	    const sha = commit.sha;
253	    const shortSha = sha.substring(0, 7);
254	
255	    // Parse conventional commit
256	    const match = firstLine.match(CONVENTIONAL_RE);
257	
258	    // Fetch files changed by this commit
259	    const commitDetail = await octokit.rest.repos.getCommit({
260	      owner,
261	      repo,
262	      ref: sha,
263	    });
264	    const changedFiles = (commitDetail.data.files || []).map((f) => f.filename);
265	
266	    // Map changed files to packages
267	    const touchedPackages = new Set();
268	    for (const file of changedFiles) {
269	      const pkg = fileToPackage(file, packagePaths);
270	      if (pkg) touchedPackages.add(pkg);
271	    }
272	
273	    if (touchedPackages.size === 0) continue; // No versioned packages touched
274	
275	    if (!match) {
276	      // Non-conventional commit touching versioned packages
277	      const pkgList = [...touchedPackages].join(', ');
278	      warnings.push(
279	        `Commit \`${shortSha}\` touches \`${pkgList}\` but has non-conventional message: "${firstLine}"`
280	      );
281	      continue;
282	    }
283	
284	    const type = match.groups.type;
285	    const isBreaking = match.groups.breaking === '!' || message.includes('BREAKING CHANGE:');
286	
287	    for (const pkg of touchedPackages) {
288	      // Track all commit types for exemption logic
289	      if (!packageCommitTypes.has(pkg)) packageCommitTypes.set(pkg, new Set());
290	      packageCommitTypes.get(pkg).add(type);
291	
292	      // Determine bump
293	      let bumpInfo;
294	      if (isBreaking) {
295	        bumpInfo = { bump: 'major', label: 'breaking', source: `breaking commit ${shortSha}` };
296	      } else if (TYPE_TO_BUMP[type]) {
297	        bumpInfo = {
298	          bump: TYPE_TO_BUMP[type].bump,
299	          label: TYPE_TO_BUMP[type].label,
300	          source: `${type} commit ${shortSha}`,
301	        };
302	      } else {
303	        // Exempt type (docs, test, chore, etc.) — no bump
304	        continue;
305	      }
306	
307	      const existing = packageBumps.get(pkg);
308	      if (!existing || BUMP_LEVELS[bumpInfo.bump] > BUMP_LEVELS[existing.bump]) {
309	        packageBumps.set(pkg, bumpInfo);
310	      }
311	    }
312	  }
313	
314	  // ------ Section 3: Auto-Exemptions (D-39) ------
315	  // If ALL commits for a package have only exempt types, that package gets no label
316	  for (const [pkg, types] of packageCommitTypes.entries()) {
317	    const allExempt = [...types].every((t) => EXEMPT_TYPES.has(t));
318	    if (allExempt) {
319	      packageBumps.delete(pkg);
320	    }
321	  }
322	
323	  // ------ Section 4: API Lock Group (D-05) ------
324	  let apiGroupBump = 'none';
325	  let apiGroupLabel = '';
326	  let apiGroupSource = '';
327	
328	  for (const member of API_LOCK_GROUP) {
329	    const bump = packageBumps.get(member);
330	    if (bump && BUMP_LEVELS[bump.bump] > BUMP_LEVELS[apiGroupBump]) {
331	      apiGroupBump = bump.bump;
332	      apiGroupLabel = bump.label;
333	      apiGroupSource = bump.source;
334	    }
335	  }
336	
337	  if (apiGroupBump !== 'none') {
338	    for (const member of API_LOCK_GROUP) {
339	      packageBumps.set(member, {
340	        bump: apiGroupBump,
341	        label: apiGroupLabel,
342	        source: apiGroupSource,
343	      });
344	    }
345	  }
346	
347	  // ------ Section 5: Monotonic Versioning (D-08, D-13) ------
348	  // For web and desktop, patch -> minor (they don't have patch releases)
349	  for (const app of MONOTONIC_APPS) {
350	    const bump = packageBumps.get(app);
351	    if (bump && bump.bump === 'patch') {
352	      packageBumps.set(app, { ...bump, bump: 'minor' });
353	    }
354	  }
355	
356	  // ------ Section 6: Cascade Detection (D-21, D-22, D-23, D-24) ------
357	  const jsReverse = buildReverseDeps(JS_DEPS);
358	  const rustReverse = buildReverseDeps(RUST_DEPS);
359	  const allReverse = {};
360	  for (const [dep, dependents] of Object.entries(jsReverse)) {
361	    allReverse[dep] = [...(allReverse[dep] || []), ...dependents];
362	  }
363	  for (const [dep, dependents] of Object.entries(rustReverse)) {
364	    allReverse[dep] = [...(allReverse[dep] || []), ...dependents];
365	  }
366	
367	  /** @type {Array<{from: string, to: string, fromBump: string, toBump: string}>} */
368	  const cascadeDetails = [];
369	
370	  // Iterate bumped packages and cascade to dependents
371	  // We need to iterate in dependency order (leaves first) to propagate transitively
372	  // Keep cascading until no new bumps are found
373	  let changed = true;
374	  while (changed) {
375	    changed = false;
376	    for (const [pkg, bumpInfo] of [...packageBumps.entries()]) {
377	      const dependents = allReverse[pkg] || [];
378	      for (const dependent of dependents) {
379	        // Cascade rules (D-22):
380	        //   major -> dependent gets at minimum minor
381	        //   minor/patch -> dependent gets at minimum patch
382	        let cascadeBump = 'patch';
383	        if (bumpInfo.bump === 'major') {
384	          cascadeBump = 'minor';
385	        }
386	
387	        const existing = packageBumps.get(dependent);
388	        if (!existing || BUMP_LEVELS[cascadeBump] > BUMP_LEVELS[existing.bump]) {
389	          const wasNew = !existing;
390	          const cascadeLabel = cascadeBump === 'minor' ? 'feat' : 'fix';
391	          packageBumps.set(dependent, {
392	            bump: cascadeBump,
393	            label:
394	              existing?.label && BUMP_LEVELS[existing.bump] >= BUMP_LEVELS[cascadeBump]
395	                ? existing.label
396	                : cascadeLabel,
397	            source: `Cascade (${PATH_TO_LABEL[pkg] || pkg} ${bumpInfo.bump})`,
398	          });
399	          if (wasNew || BUMP_LEVELS[cascadeBump] > BUMP_LEVELS[existing?.bump ?? 'none']) {
400	            cascadeDetails.push({
401	              from: pkg,
402	              to: dependent,
403	              fromBump: bumpInfo.bump,
404	              toBump: cascadeBump,
405	            });
406	            changed = true;
407	          }
408	        }
409	      }
410	    }
411	  }
412	
413	  // Apply monotonic versioning again for cascaded bumps on web/desktop
414	  for (const app of MONOTONIC_APPS) {
415	    const bump = packageBumps.get(app);
416	    if (bump && bump.bump === 'patch') {
417	      packageBumps.set(app, { ...bump, bump: 'minor' });
418	    }
419	  }
420	
421	  // Re-apply API lock group after cascading
422	  apiGroupBump = 'none';
423	  apiGroupLabel = '';
424	  apiGroupSource = '';
425	  for (const member of API_LOCK_GROUP) {
426	    const bump = packageBumps.get(member);
427	    if (bump && BUMP_LEVELS[bump.bump] > BUMP_LEVELS[apiGroupBump]) {
428	      apiGroupBump = bump.bump;
429	      apiGroupLabel = bump.label;
430	      apiGroupSource = bump.source;
431	    }
432	  }
433	  if (apiGroupBump !== 'none') {
434	    for (const member of API_LOCK_GROUP) {
435	      const existing = packageBumps.get(member);
436	      if (!existing || BUMP_LEVELS[apiGroupBump] > BUMP_LEVELS[existing.bump]) {
437	        packageBumps.set(member, {
438	          bump: apiGroupBump,
439	          label: apiGroupLabel,
440	          source: apiGroupSource,
441	        });
442	      }
443	    }
444	  }
445	
446	  // ------ Section 7: Label Application (D-16, D-18) ------
447	
448	  // Collapse package paths to label components (highest bump per component)
449	  /** @type {Map<string, {bump: string, label: string, source: string}>} */
450	  const componentBumps = new Map();
451	
452	  for (const [pkg, bumpInfo] of packageBumps.entries()) {
453	    const component = PATH_TO_LABEL[pkg];
454	    if (!component) continue;
455	
456	    const existing = componentBumps.get(component);
457	    if (!existing || BUMP_LEVELS[bumpInfo.bump] > BUMP_LEVELS[existing.bump]) {
458	      componentBumps.set(component, bumpInfo);
459	    }
460	  }
461	
462	  // Determine label type for each component
463	  /** @type {Map<string, string>} */
464	  const computedLabels = new Map();
465	  for (const [component, bumpInfo] of componentBumps.entries()) {
466	    let labelType;
467	    if (bumpInfo.bump === 'major') {
468	      labelType = 'breaking';
469	    } else {
470	      labelType = bumpInfo.label;
471	    }
472	    computedLabels.set(component, `release:${component}:${labelType}`);
473	  }
474	
475	  // Fetch current labels on the PR
476	  const currentReleaseLabels = existingLabels.filter(
477	    (l) => l.startsWith('release:') && l !== 'release:none'
478	  );
479	
480	  // Determine which existing release labels are manual overrides (D-18)
481	  const manualOverrides = [];
482	
483	  // Group existing labels by component
484	  /** @type {Map<string, string>} */
485	  const existingByComponent = new Map();
486	  for (const label of currentReleaseLabels) {
487	    const parts = label.split(':');
488	    if (parts.length === 3) {
489	      existingByComponent.set(parts[1], label);
490	    }
491	  }
492	
493	  // Labels to add and remove
494	  const labelsToAdd = [];
495	  const labelsToRemove = [];
496	
497	  // Label type → bump level for comparison
498	  const LABEL_BUMP_LEVEL = { fix: 1, perf: 1, refactor: 1, feat: 2, breaking: 3 };
499	
500	  for (const [component, computedLabel] of computedLabels.entries()) {
501	    const existing = existingByComponent.get(component);
502	    if (existing && existing !== computedLabel) {
503	      const existingLevel = LABEL_BUMP_LEVEL[existing.split(':')[2]] ?? 0;
504	      const computedLevel = LABEL_BUMP_LEVEL[computedLabel.split(':')[2]] ?? 0;
505	
506	      if (computedLevel > existingLevel) {
507	        // Computed bump is higher — replace existing label (e.g. fix→feat after force-push)
508	        labelsToRemove.push(existing);
509	        labelsToAdd.push(computedLabel);
510	      } else {
511	        // Existing label is higher or equal — treat as manual override
512	        manualOverrides.push({
513	          component,
514	          existing,
515	          computed: computedLabel,
516	        });
517	      }
518	    } else if (!existing) {
519	      labelsToAdd.push(computedLabel);
520	    }
521	    // If existing matches computed, no action needed
522	  }
523	
524	  // Remove labels for components no longer computed
525	  // (but only if they appear to be auto-applied, not manual overrides)
526	  for (const [component, existingLabel] of existingByComponent.entries()) {
527	    if (!computedLabels.has(component)) {
528	      // Component no longer has a computed bump — check if it was auto-applied
529	      // Heuristic: remove it (force-push may have changed commits)
530	      labelsToRemove.push(existingLabel);
531	    }
532	  }
533	
534	  // Apply label changes
535	  for (const label of labelsToAdd) {
536	    try {
537	      await octokit.rest.issues.addLabels({
538	        owner,
539	        repo,
540	        issue_number: prNumber,
541	        labels: [label],
542	      });
543	      core.info(`Added label: ${label}`);
544	    } catch (err) {
545	      core.warning(`Could not add label "${label}": ${err.message}`);
546	    }
547	  }
548	
549	  for (const label of labelsToRemove) {
550	    try {
551	      await octokit.rest.issues.removeLabel({
552	        owner,
553	        repo,
554	        issue_number: prNumber,
555	        name: label,
556	      });
557	      core.info(`Removed label: ${label}`);
558	    } catch (err) {
559	      // Label might not exist — that's fine
560	      if (err.status !== 404) {
561	        core.warning(`Could not remove label "${label}": ${err.message}`);
562	      }
563	    }
564	  }
565	
566	  // ------ Section 8: PR Comment (D-23) ------
567	  const commentLines = [COMMENT_MARKER, '## Release Preview', ''];
568	
569	  if (componentBumps.size === 0 && warnings.length === 0) {
570	    commentLines.push(
571	      'No version bumps detected. All changes are in unversioned paths or use exempt commit types.'
572	    );
573	  } else {
574	    if (componentBumps.size > 0) {
575	      commentLines.push(
576	        '| Package | Bump | Label | Source |',
577	        '| ------- | ---- | ----- | ------ |'
578	      );
579	
580	      // Sort components alphabetically for stable output
581	      const sortedComponents = [...componentBumps.entries()].sort(([a], [b]) => a.localeCompare(b));
582	
583	      for (const [component, bumpInfo] of sortedComponents) {
584	        const label = computedLabels.get(component);
585	        const isDirect = !bumpInfo.source.startsWith('Cascade');
586	        const source = isDirect ? `Direct (${bumpInfo.label} commit)` : bumpInfo.source;
587	        commentLines.push(`| ${component} | ${bumpInfo.bump} | \`${label}\` | ${source} |`);
588	      }
589	    }
590	
591	    if (cascadeDetails.length > 0) {
592	      commentLines.push('', '### Cascade Details', '');
593	      // Deduplicate cascade details
594	      const seen = new Set();
595	      for (const detail of cascadeDetails) {
596	        const fromLabel = PATH_TO_LABEL[detail.from] || detail.from;
597	        const toLabel = PATH_TO_LABEL[detail.to] || detail.to;
598	        const key = `${fromLabel}->${toLabel}`;
599	        if (seen.has(key)) continue;
600	        seen.add(key);
601	        commentLines.push(
602	          `- \`${fromLabel}\` ${detail.fromBump} -> \`${toLabel}\` ${detail.toBump} (direct dependency)`
603	        );
604	      }
605	    }
606	
607	    if (manualOverrides.length > 0) {
608	      commentLines.push('', '### Manual Overrides', '');
609	      for (const override of manualOverrides) {
610	        commentLines.push(
611	          `- **${override.component}**: keeping manual label \`${override.existing}\` (computed: \`${override.computed}\`)`
612	        );
613	      }
614	    }
615	
616	    if (warnings.length > 0) {
617	      commentLines.push('', '### Warnings', '');
618	      for (const warning of warnings) {
619	        commentLines.push(`- ${warning}`);
620	      }
621	    }
622	  }
623	
624	  await postOrUpdateComment(octokit, owner, repo, prNumber, commentLines.join('\n'));
625	
626	  // ------ Section 9: CI Check Status (D-19) ------
627	  if (warnings.length > 0) {
628	    core.setFailed(
629	      `${warnings.length} commit(s) touching versioned packages have non-conventional messages. ` +
630	        'Fix commit messages or add the `release:none` label to skip enforcement.'
631	    );
632	  }
633	}
634	
635	/**
636	 * Post or update the release preview comment on the PR.
637	 * @param {ReturnType<typeof github.getOctokit>} octokit
638	 * @param {string} owner
639	 * @param {string} repo
640	 * @param {number} prNumber
641	 * @param {string} body
642	 */
643	async function postOrUpdateComment(octokit, owner, repo, prNumber, body) {
644	  // Find existing comment with marker
645	  const comments = await fetchAllPages(
646	    octokit,
647	    'GET /repos/{owner}/{repo}/issues/{issue_number}/comments',
648	    { owner, repo, issue_number: prNumber }
649	  );
650	
651	  const existing = comments.find((c) => c.body && c.body.includes(COMMENT_MARKER));
652	
653	  if (existing) {
654	    await octokit.rest.issues.updateComment({
655	      owner,
656	      repo,
657	      comment_id: existing.id,
658	      body,
659	    });
660	    core.info(`Updated release preview comment (ID: ${existing.id})`);
661	  } else {
662	    await octokit.rest.issues.createComment({
663	      owner,
664	      repo,
665	      issue_number: prNumber,
666	      body,
667	    });
668	    core.info('Created release preview comment');
669	  }
670	}
671	
672	// ---------------------------------------------------------------------------
673	// Entry point
674	// ---------------------------------------------------------------------------
675	
676	run().catch((err) => {
677	  core.setFailed(`PR release preview failed: ${err.message}`);
678	});
